insert into public.foods (id, name_fa, name_en, source, kcal_100g, protein_100g, carbs_100g, fat_100g, cooked_factor, state, confidence, tags, source_ref, notes) values
  ('fa:chelo', 'چلو (برنج سفید پخته با روغن)', 'Chelo (cooked white rice, home style with oil)', 'fa_manual', 155, 2.7, 28.2, 3.1, 1, 'as_served', 'medium', ARRAY['rice','staple','grain']::text[], 'USDA SR Legacy FDC 168878 (rice white long-grain cooked) + canola oil FDC 172336', 'فرض دستور: ۱ قاشق غذاخوری روغن (۱۴ گرم) به ازای هر ۵۰۰ گرم برنج پخته ≈ ۲٫۸ گرم روغن در ۱۰۰ گرم. برنج پخته ساده USDA: 130 kcal / 2.69 p / 28.2 c / 0.28 f. ته‌دیگ و کره‌زیاد جداگانه ثبت شود.'),
  ('fa:berenj-kham', 'برنج خام (سفید دانه‌بلند)', 'Rice, white, long-grain, raw', 'usda', 365, 7.13, 80, 0.66, 2.6, 'raw', 'medium', ARRAY['rice','staple','grain','raw']::text[], 'USDA SR Legacy FDC 169756', 'cooked_factor ≈ ۲٫۶ از نسبت USDA (۱۸۵ گرم خام ≈ ۴۷۴ گرم پخته). برای آبکش ایرانی ممکن است تا ۲٫۸ باشد؛ نیاز به وزن‌کشی خانگی.'),
  ('fa:nan-sangak', 'نان سنگک', 'Sangak bread', 'fa_manual', 262, 9.8, 55.9, 1.7, 1, 'as_served', 'medium', ARRAY['bread','wholewheat','iranian']::text[], 'Proxy: USDA SR Legacy whole-wheat pita (NDB 18414) scaled per 100 g', 'جدول رسمی ترکیبات نان سنگک پیدا نشد؛ از پیتای سبوس‌دار USDA به‌عنوان نزدیک‌ترین نان تخت سبوس‌دار بدون چربی استفاده شد. فیبر ≈ ۶ گرم. بازبین باید با نانوایی‌های تورنتو کالیبره کند.'),
  ('fa:nan-barbari', 'نان بربری', 'Barbari bread', 'fa_manual', 275, 9.1, 55.7, 1.2, 1, 'as_served', 'low', ARRAY['bread','white','iranian']::text[], 'Proxy: USDA SR Legacy white pita enriched (NDB 18413) scaled per 100 g', 'پروکسی: پیتای سفید USDA. بربری به‌خاطر رومال و کنجد کمی چربی بیشتری دارد؛ یک منبع فارسی غیررسمی ۳۶۰ kcal داده که با رطوبت نان تازه نمی‌خواند. اعتماد پایین تا وزن‌کشی و بازبینی.'),
  ('fa:nan-lavash', 'نان لواش', 'Lavash bread', 'fa_manual', 275, 9.1, 55.7, 1.2, 1, 'as_served', 'medium', ARRAY['bread','white','iranian','thin']::text[], 'Proxy: USDA SR Legacy white pita enriched (NDB 18413); FatSecret generic lavash 238 kcal and Fitatu 283 kcal per 100 g as cross-checks', 'USDA Survey (FNDDS) ورودی لواش در این نشست به‌خاطر محدودیت API قابل دریافت نبود؛ پیتای سفید به‌عنوان پروکسی. لواش نازک خشک‌تر است و ممکن است تا ۳۰۰ kcal برسد.'),
  ('fa:morgh-grill-sineh', 'مرغ گریل (سینه بدون پوست)', 'Chicken breast, skinless, grilled/roasted', 'usda', 165, 31, 0, 3.57, 0.75, 'cooked', 'medium', ARRAY['chicken','protein','lean']::text[], 'USDA SR Legacy FDC 171477', 'بدون روغن اضافه. cooked_factor ۰٫۷۵: حدود ۲۵٪ افت وزن در پخت (USDA yield). اگر با روغن سرخ یا گریل شده، روغن جدا ثبت شود.'),
  ('fa:morgh-sorkhshodeh', 'مرغ سرخ‌شده (با پوست)', 'Chicken breast with skin, pan-fried, flour-coated', 'usda', 222, 31.8, 1.64, 8.87, 0.7, 'cooked', 'medium', ARRAY['chicken','protein','fried']::text[], 'USDA SR Legacy FDC 171476', 'نزدیک‌ترین ورودی USDA به مرغ سرخ‌شده خانگی (قبلاً پخته سپس با زردچوبه و روغن سرخ‌شده). ران با پوست چرب‌تر است (~۲۶۰ kcal)؛ بازبین می‌تواند ردیف ران اضافه کند.'),
  ('fa:gusht-gusaleh-khoreshti', 'گوشت گوساله خورشتی (پخته)', 'Beef chuck stew meat, braised', 'usda', 194, 32.5, 0, 7.14, 0.65, 'cooked', 'medium', ARRAY['beef','protein','stew']::text[], 'USDA SR Legacy FDC 171205', 'گوشت خورشتی پخته بدون روغن اضافه. cooked_factor ۰٫۶۵ (افت ~۳۵٪ در پخت آرام). روغن خورش در ردیف خورش حساب شده.'),
  ('fa:ghormeh-sabzi', 'قورمه‌سبزی (خورش بدون برنج)', 'Ghormeh sabzi stew (no rice)', 'fa_manual', 137, 11.4, 7.8, 7.1, 1, 'as_served', 'low', ARRAY['stew','herb','beef','iranian','mixed']::text[], 'Recipe-derived from USDA SR Legacy ingredients (beef chuck braised FDC 171205; parsley; onion; kidney beans cooked; canola oil)', 'فرض دستور (۴ نفر): ۵۰۰ گرم گوشت خام (≈۳۲۵ گرم پخته)، ۶۰۰ گرم سبزی خام، ۱۵۰ گرم پیاز، ۲۰۰ گرم لوبیا قرمز پخته، ۶۰ گرم روغن، لیمو عمانی؛ وزن نهایی ≈ ۱۲۵۰ گرم. روغن و نسبت گوشت بین خانه‌ها بسیار متغیر است (±۳۰٪). حاوی فیبر.'),
  ('fa:gheymeh', 'قیمه (خورش بدون برنج، با سیب‌زمینی سرخ‌کرده)', 'Gheymeh stew with fried potato topping (no rice)', 'fa_manual', 170, 11, 14, 7.2, 1, 'as_served', 'low', ARRAY['stew','beef','splitpea','iranian','mixed']::text[], 'Recipe-derived from USDA SR Legacy ingredients (beef chuck braised; split peas; onion; tomato paste; canola oil; french-fried potato)', 'فرض دستور (۴ نفر): ۵۰۰ گرم گوشت خام، ۱۵۰ گرم لپه خشک، ۱۵۰ گرم پیاز، ۶۰ گرم رب، ۶۰ گرم روغن، ۲۰۰ گرم سیب‌زمینی سرخ‌کرده؛ وزن نهایی ≈ ۱۴۰۰ گرم. بدون سیب‌زمینی ≈ ۱۵۰ kcal. حاوی فیبر.'),
  ('fa:kabab-kubideh', 'کباب کوبیده (پخته)', 'Kabab koobideh, grilled', 'fa_manual', 236, 22, 1.5, 15, 0.72, 'cooked', 'medium', ARRAY['kebab','beef','grilled','iranian']::text[], 'Recipe-derived: USDA SR Legacy ground beef 80/20 patty broiled (FDC 174036) + ~15% grated onion', 'فرض: مخلوط ۸۳٪ گوشت چرخ‌کرده ۸۰/۲۰ و ۱۷٪ پیاز رنده‌شده، کباب‌شده روی آتش. cooked_factor ۰٫۷۲ (افت آب و چربی). کوبیده رستورانی با گوشت چرب‌تر تا ۲۸۰ kcal می‌رسد.'),
  ('fa:jujeh-kabab', 'جوجه‌کباب (سینه، پخته)', 'Joojeh kabab (chicken breast, grilled, marinated)', 'fa_manual', 181, 30, 0.5, 6.5, 0.75, 'cooked', 'medium', ARRAY['kebab','chicken','grilled','iranian']::text[], 'Recipe-derived: USDA SR Legacy chicken breast roasted (FDC 171477) + ~3 g absorbed oil/butter per 100 g cooked', 'فرض: مریناد ماست/زعفران/لیمو/پیاز (ماکروی ناچیز) + حدود ۳ گرم روغن یا کره جذب‌شده در ۱۰۰ گرم پخته. جوجه با استخوان و ران چرب‌تر است.'),
  ('fa:salad-shirazi', 'سالاد شیرازی', 'Shirazi salad', 'fa_manual', 37, 0.8, 4.5, 2.1, 1, 'as_served', 'medium', ARRAY['salad','vegetable','iranian']::text[], 'Recipe-derived from USDA SR Legacy (cucumber FDC 168409; tomato FDC 170457; onion; lemon juice; olive oil)', 'فرض دستور: ۳۰۰ گرم خیار، ۳۰۰ گرم گوجه، ۱۰۰ گرم پیاز، ۳۰ گرم آبلیمو، ۱۵ گرم روغن زیتون (≈۷۴۵ گرم). بدون روغن ≈ ۲۰ kcal. حاوی فیبر.'),
  ('fa:mast', 'ماست ساده پرچرب', 'Yogurt, plain, whole milk', 'usda', 61, 3.47, 4.66, 3.25, 1, 'as_served', 'medium', ARRAY['dairy','yogurt']::text[], 'USDA SR Legacy FDC 171284', 'ماست ۳٫۲۵٪ چربی. ماست چکیده/یونانی ≈ ۹۷ kcal و ۹ گرم پروتئین (FDC 171304)؛ ماست کم‌چرب ≈ ۶۳ kcal با ۱٫۵٪ چربی. بازبین می‌تواند ردیف‌های جدا اضافه کند.'),
  ('fa:dugh', 'دوغ (خانگی، ماست و آب ۱:۱)', 'Doogh (homemade, yogurt:water 1:1)', 'fa_manual', 31, 1.7, 2.3, 1.6, 1, 'as_served', 'medium', ARRAY['dairy','drink','iranian']::text[], 'Derived: 50% USDA SR Legacy whole-milk yogurt FDC 171284 + 50% water', 'فرض: نیمی ماست پرچرب، نیمی آب، نمک و نعناع (ماکروی ناچیز). دوغ صنعتی معمولاً رقیق‌تر و با چربی ۱ تا ۱٫۵٪ است (≈۲۵ kcal).'),
  ('fa:panir-feta', 'پنیر لیقوان / فتا', 'Feta / Lighvan-style brined cheese', 'usda', 265, 14.2, 3.88, 21.5, 1, 'as_served', 'medium', ARRAY['dairy','cheese','brined']::text[], 'USDA SR Legacy FDC 173420', 'لیقوان گوسفندی معمولاً چرب‌تر از فتای صنعتی کانادایی است؛ تفاوت حدود ±۱۵٪. پنیر آب‌پنیری کم‌چرب جدا ثبت شود.'),
  ('fa:tokhm-morgh', 'تخم‌مرغ (کامل، خام)', 'Egg, whole, raw', 'usda', 143, 12.6, 0.72, 9.51, 1, 'raw', 'medium', ARRAY['egg','protein']::text[], 'USDA SR Legacy FDC 171287', 'مقادیر برای تخم‌مرغ بدون پوست. آب‌پز تقریباً همین مقدار؛ نیمرو روغنش جدا حساب می‌شود.'),
  ('fa:kareh', 'کره (نمک‌دار)', 'Butter, salted', 'usda', 717, 0.85, 0.06, 81.1, 1, 'as_served', 'medium', ARRAY['fat','dairy','butter']::text[], 'USDA SR Legacy FDC 173410', 'کره بی‌نمک تقریباً همین مقدار (FDC 173430).'),
  ('fa:roghan-maye', 'روغن مایع (کانولا)', 'Vegetable oil, canola', 'usda', 884, 0, 0, 100, 1, 'as_served', 'medium', ARRAY['fat','oil']::text[], 'USDA SR Legacy FDC 172336', 'همه روغن‌های مایع (آفتابگردان، ذرت، زیتون) تقریباً ۸۸۴ kcal در ۱۰۰ گرم دارند.'),
  ('fa:khiar', 'خیار (با پوست، خام)', 'Cucumber, with peel, raw', 'usda', 15, 0.65, 3.63, 0.11, 1, 'raw', 'medium', ARRAY['vegetable','raw']::text[], 'USDA SR Legacy FDC 168409', 'انرژی USDA با ضرایب اختصاصی و فیبر ۰٫۵ گرم محاسبه شده؛ به همین دلیل کمتر از ۴/۴/۹ است.'),
  ('fa:gojeh', 'گوجه‌فرنگی (خام)', 'Tomato, red, ripe, raw', 'usda', 18, 0.88, 3.89, 0.2, 1, 'raw', 'medium', ARRAY['vegetable','raw']::text[], 'USDA SR Legacy FDC 170457', 'فیبر ۱٫۲ گرم؛ انرژی USDA کمی کمتر از جمع ۴/۴/۹ است.'),
  ('fa:adasi', 'عدسی (خوراک عدس با پیاز و روغن)', 'Adasi (lentil stew)', 'fa_manual', 105, 5.8, 15.3, 2.5, 1, 'as_served', 'medium', ARRAY['lentil','legume','iranian','mixed']::text[], 'Recipe-derived from USDA SR Legacy (lentils raw/cooked FDC 172421; onion; canola oil)', 'فرض دستور: ۳۰۰ گرم عدس خشک، ۱۰۰ گرم پیاز، ۳۰ گرم روغن، آب تا وزن نهایی ≈ ۱۳۰۰ گرم. عدس پخته ساده USDA: ۱۱۶ kcal / ۹ p / ۲۰ c / ۰٫۴ f. حاوی فیبر.'),
  ('fa:ash-reshteh', 'آش رشته', 'Ash reshteh (noodle and legume soup)', 'fa_manual', 79, 3.8, 11.5, 2.2, 1, 'as_served', 'low', ARRAY['soup','ash','legume','iranian','mixed']::text[], 'Recipe-derived from USDA SR Legacy ingredients (lentils; chickpeas; kidney beans; wheat noodles; herbs; spinach; onion; canola oil; kashk approximated as concentrated whey)', 'فرض دستور: ۱۰۰ گرم عدس، ۱۰۰ گرم نخود، ۱۰۰ گرم لوبیا، ۲۰۰ گرم رشته، ۵۰۰ گرم سبزی، ۲۰۰ گرم اسفناج، ۲۰۰ گرم پیاز، ۶۰ گرم روغن، ۱۵۰ گرم کشک؛ وزن نهایی ≈ ۳۵۰۰ گرم. غلظت آش و پیاز داغ/کشک روی آن بسیار متغیر است. حاوی فیبر.'),
  ('fa:khorma', 'خرما (مجول)', 'Dates, medjool', 'usda', 277, 1.81, 74.97, 0.15, 1, 'as_served', 'medium', ARRAY['fruit','dried','date']::text[], 'USDA SR Legacy FDC 168191', 'فیبر ۶٫۷ گرم؛ انرژی USDA کمتر از جمع ۴/۴/۹. خرمای مضافتی رطوبت بیشتری دارد و احتمالاً ۲۳۰ تا ۲۶۰ kcal است؛ منبع معتبر پیدا نشد.'),
  ('fa:gerdu', 'گردو (مغز)', 'Walnuts, English, kernels', 'usda', 654, 15.23, 13.71, 65.21, 1, 'raw', 'medium', ARRAY['nut','snack','fat']::text[], 'USDA SR Legacy FDC 170187', 'فیبر ۶٫۷ گرم؛ انرژی USDA کمتر از جمع ۴/۴/۹ است.'),
  ('fa:chay', 'چای (دم‌کرده، بدون قند)', 'Black tea, brewed, unsweetened', 'usda', 1.2, 0, 0.3, 0, 1, 'as_served', 'medium', ARRAY['drink','tea','iranian']::text[], 'USDA SR Legacy: tea, black, brewed (≈1 kcal and 0.3 g carbohydrate per 100 g; record id to confirm)', 'بدون قند و شیر. قند، نبات یا خرمای کنار چای جداگانه ثبت شود.')
